const FURI_MAP = new Map<string, string[]>();
FURI_RAW.split("\n").forEach((l: string) => {
  const k = l.indexOf(":");
  if (k > 0) FURI_MAP.set(l.slice(0, k), l.slice(k + 1).split(","));
});
const KRUN_RE = /[\u3400-\u9fff々〆ヶ]+/g;
function furiK(key: string, s: string): string {
  const rs = FURI_MAP.get(key);
  if (!rs) return s;
  let i = 0;
  return s.replace(KRUN_RE, (m: string) => {
    const r = rs[i++];
    if (!r) return m;
    if (!r.includes(";")) return `${m}[${r}]`;
    let p = 0;
    return r
      .split(";")
      .map((sg: string) => {
        const d = sg.indexOf(".");
        const n = Number(sg.slice(0, d));
        const b = m.slice(p, p + n);
        p += n;
        return `${b}[${sg.slice(d + 1)}]`;
      })
      .join("");
  });
}
function isHira(c: string): boolean {
  return c.charCodeAt(0) < 0x30a0;
}

let RATE = 0.9;
let LAST_TAP = 0;
if (typeof window !== "undefined") window.addEventListener("pointerdown", () => { LAST_TAP = Date.now(); }, { capture: true, passive: true });
let JA_VOICE: SpeechSynthesisVoice | null = null;
function jaVoice(): SpeechSynthesisVoice | null {
  if (JA_VOICE) return JA_VOICE;
  try {
    const vs = window.speechSynthesis.getVoices().filter((x: SpeechSynthesisVoice) => x.lang.toLowerCase().replace("_", "-").startsWith("ja"));
    JA_VOICE = vs.find((x: SpeechSynthesisVoice) => /kyoko|otoya|o-ren|google/i.test(x.name)) ?? vs[0] ?? null;
  } catch {
    JA_VOICE = null;
  }
  return JA_VOICE;
}
if (typeof window !== "undefined") {
  try {
    window.speechSynthesis?.addEventListener?.("voiceschanged", () => {
      JA_VOICE = null;
    });
  } catch {
    /* 無語音 */
  }
  // iOS：第一次觸控時先播一個無聲片段，解鎖之後自動播放（聽力題）的語音
  const unlock = (): void => {
    window.removeEventListener("touchend", unlock);
    window.removeEventListener("click", unlock);
    try {
      const ss = window.speechSynthesis;
      if (!ss || ss.speaking) return;
      const u = new SpeechSynthesisUtterance(" ");
      u.volume = 0;
      u.lang = "ja-JP";
      ss.speak(u);
    } catch {
      /* 無語音 */
    }
  };
  window.addEventListener("touchend", unlock, { passive: true });
  window.addEventListener("click", unlock);
}
function speakerPitch(who: string): number {
  return /男|先生|店員|部長|父|兄|弟|夫/.test(who) && !/女/.test(who) ? 0.72 : /女|母|姉|妹|妻/.test(who) ? 1.32 : 1;
}
function speak(text: string, rate?: number): void {
  try {
    const ss = window.speechSynthesis;
    if (!ss) return;
    const v = jaVoice();
    const us = text.split("＃").map((part: string) => {
      const m = /^([^：]{1,12})：/.exec(part);
      const u = new SpeechSynthesisUtterance(kanaOf(m ? part.slice(m[0].length) : part));
      u.lang = "ja-JP";
      u.rate = rate ?? RATE;
      if (m) u.pitch = speakerPitch(m[1] ?? "");
      if (v) u.voice = v;
      return u;
    });
    const go = () => us.forEach((u: SpeechSynthesisUtterance) => ss.speak(u));
    if (ss.paused) ss.resume();
    // iOS Safari：cancel 後立刻 speak 常被吃掉，所以只在正在播放時才 cancel，並稍等一下再播
    if (ss.speaking || ss.pending) {
      ss.cancel();
      window.setTimeout(go, 60);
    } else go();
  } catch {
    /* 不支援語音 */
  }
}

/* ============ 儲存（localStorage） ============ */
type WrongItem = { id: string; sec: Sec; prompt: string; ans: string; exp: string; t: number; n: number };
type DBT = {
  stats: Record<string, { c: number; w: number }>;
  wrong: WrongItem[];
  weak: Record<string, { w: number; r: number }>;
  known: Record<string, number>;
  lyrics: string;
  furi: boolean;
  best: Record<string, number>;
  srs: Record<string, { due: number; st: number }>;
  ks: Record<string, { c: number; n: number }>;
  daily: { d: string; c: Record<string, number> };
  hist: Record<string, number>;
  onb: number;
  kj: Record<string, { c: number; w: number }>;
  vsrs: Record<string, { due: number; iv: number; ef: number; n: number }>;
  vsrsNew: { d: number; n: number };
  vsrsPer: number;
  lyr: Record<string, string>;
  fav: Record<string, number>;
  goal?: number;
  log?: LogE[];
  wq?: Record<string, Q>;
  exams?: ExamRes[];
};
const KEY = "n3_practice_v1";
let STORAGE_OK = true;
function freshDB(): DBT {
  return { stats: {}, wrong: [], weak: {}, known: {}, lyrics: "", furi: true, best: {}, srs: {}, ks: {}, daily: { d: "", c: {} }, hist: {}, onb: 0, kj: {}, vsrs: {}, vsrsNew: { d: 0, n: 0 }, vsrsPer: 10, lyr: {}, fav: {} };
}
function loadDB(): DBT {
  const base = freshDB();
  try {
    const s = window.localStorage.getItem(KEY);
    if (s) {
      const p = JSON.parse(s) as Partial<DBT>;
      return { ...base, ...p };
    }
  } catch {
    STORAGE_OK = false;
  }
  return base;
}
let DB: DBT = loadDB();
const LISTENERS = new Set<() => void>();
function commit(): void {
  try {
    window.localStorage.setItem(KEY, JSON.stringify(DB));
  } catch {
    STORAGE_OK = false;
  }
  LISTENERS.forEach((f: () => void) => f());
}
function useDB(): DBT {
  const [, setN] = useState(0);
  useEffect(() => {
    const f = () => setN((n: number) => n + 1);
    LISTENERS.add(f);
    return () => {
      LISTENERS.delete(f);
    };
  }, []);
  return DB;
}

type Q = {
  id: string;
  sec: Sec;
  tag?: string;
  prompt: string;
  big?: boolean;
  ja?: boolean;
  passage?: string;
  options: string[];
  answer: number;
  exp?: string;
  tts?: string;
  ttsAfter?: boolean;
  autoPlay?: boolean;
  reveal?: string;
  review?: string;
  optJa?: boolean;
  noReview?: boolean;
  kana?: string[];
  cat?: string;
  tags?: string[];
};

function dkey(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function today(): string {
  return dkey(new Date());
}
function recordStat(sec: Sec, ok: boolean): void {
  const s = DB.stats[sec] ?? { c: 0, w: 0 };
  DB.stats = { ...DB.stats, [sec]: ok ? { c: s.c + 1, w: s.w } : { c: s.c, w: s.w + 1 } };
  const td = today();
  const dc: Record<string, number> = DB.daily.d === td ? DB.daily.c : {};
  DB.daily = { d: td, c: { ...dc, [sec]: (dc[sec] ?? 0) + 1 } };
  const h: Record<string, number> = { ...DB.hist, [td]: (DB.hist[td] ?? 0) + 1 };
  const hk = Object.keys(h).sort();
  if (hk.length > 120) delete h[hk[0] ?? ""];
  DB.hist = h;
}
function streakDays(): number {
  const d = new Date();
  if (!(DB.hist[dkey(d)] ?? 0)) d.setDate(d.getDate() - 1);
  let n = 0;
  while ((DB.hist[dkey(d)] ?? 0) > 0) {
    n++;
    d.setDate(d.getDate() - 1);
  }
  return n;
}
function record(q: Q, ok: boolean, pick?: string): void {
  logAttempt(q, ok, pick);
  recordStat(q.sec, ok);
  if (!q.noReview) {
    const prev = DB.wrong.find((x: WrongItem) => x.id === q.id);
    const rest = DB.wrong.filter((x: WrongItem) => x.id !== q.id);
    if (!ok) {
      const item: WrongItem = {
        id: q.id,
        sec: q.sec,
        prompt: q.review ?? q.prompt,
        ans: q.options[q.answer] ?? "",
        exp: q.exp ?? "",
        t: Date.now(),
        n: (prev ? prev.n : 0) + 1,
      };
      DB.wrong = [item, ...rest].slice(0, 300);
    } else {
      DB.wrong = rest;
    }
  }
  commit();
}
/* 間隔複習：答錯 → 1 分鐘後再考；到期答對 → 往下一階；9 階都過就畢業。1 小時以上的間隔隨機錯開 ±15%，讓複習分散在一天各時段 */
const SRS_STEPS = [60e3, 10 * 60e3, 3600e3, 4 * 3600e3, 9 * 3600e3, 86400e3, 3 * 86400e3, 7 * 86400e3, 21 * 86400e3];
function jit(ms: number): number {
  return ms >= 3600e3 ? Math.round(ms * (0.85 + Math.random() * 0.3)) : ms;
}
function bumpWeak(chars: string[], ok: boolean): void {
  const w = { ...DB.weak };
  const ks = { ...DB.ks };
  const srs = { ...DB.srs };
  const now = Date.now();
  chars.forEach((c: string) => {
    const e = w[c] ?? { w: 0, r: 0 };
    w[c] = ok ? { w: e.w, r: e.r + 1 } : { w: e.w + 1, r: e.r };
    const k = ks[c] ?? { c: 0, n: 0 };
    ks[c] = { c: k.c + (ok ? 1 : 0), n: k.n + 1 };
    const s = srs[c];
    if (!ok) srs[c] = { due: now + (SRS_STEPS[0] ?? 60e3), st: 0 };
    else if (s && s.due <= now) {
      const st = s.st + 1;
      if (st >= SRS_STEPS.length) delete srs[c];
      else srs[c] = { due: now + jit(SRS_STEPS[st] ?? 86400e3), st };
    }
  });
  DB.weak = w;
  DB.ks = ks;
  DB.srs = srs;
  commit();
}
function srsDue(): string[] {
  const now = Date.now();
  return Object.keys(DB.srs).filter((c: string) => (DB.srs[c]?.due ?? 0) <= now);
}
function weakScore(c: string): number {
  const e = DB.weak[c];
  if (!e) return 0;
  return Math.max(0, e.w * 2 - e.r);
}

