const LOANS: Loan[] = LOAN_RAW.split("\n").map((l: string) => {
  const [k, r, m, src] = l.split("|") as [string, string, string, string];
  return { k, r, m, src };
});
const MACRON: Record<string, string> = { ā: "a", ī: "i", ū: "u", ē: "e", ō: "o" };
const ADD_MACRON: Record<string, string> = { a: "ā", i: "ī", u: "ū", e: "ē", o: "ō" };
function romaVariants(r: string): string[] {
  const out: string[] = [];
  const strip = r.replace(/[āīūēō]/g, (ch: string) => MACRON[ch] ?? ch);
  if (strip !== r) out.push(strip);
  const fi = r.search(/[āīūēō]/);
  if (fi >= 0) out.push(r.slice(0, fi) + (strip[fi] ?? "") + r.slice(fi + 1));
  const dbl = r.match(/([kstpdgbc])\1/);
  if (dbl) out.push(r.replace(dbl[0], dbl[1] ?? ""));
  else {
    const m = r.match(/^([^aeiouāīūēō]*[aeiou])([kstp])/);
    if (m) out.push(r.replace(m[0], (m[1] ?? "") + (m[2] ?? "") + (m[2] ?? "")));
  }
  const pv = r.search(/[aeiou]/);
  if (pv >= 0) out.push(r.slice(0, pv) + (ADD_MACRON[r[pv] ?? ""] ?? "") + r.slice(pv + 1));
  return uniq(out).filter((x: string) => x !== r);
}

