type Vocab = { id: string; w: string; r: string; m: string; p: string; ex: string; tr: string };
const VOCAB: Vocab[] = VOCAB_RAW.split("\n").map((l: string, i: number) => {
  const [w, r, m, p, ex, tr] = l.split("|") as [string, string, string, string, string, string];
  return { id: "v" + i, w, r, m, p, ex: furiK("v" + i, ex), tr };
});
const POS: [string, string][] = [
  ["all", "全部"],
  ["名", "名詞"],
  ["な形", "な形容詞"],
  ["い形", "い形容詞"],
  ["動", "動詞"],
  ["副", "副詞"],
];
function posMatch(v: Vocab, key: string): boolean {
  return key === "all" || v.p.split("・").some((x: string) => x.startsWith(key));
}
