type KW = { k: string; r: string; m: string; cat: string };
const KWORDS: KW[] = [
  ...LOANS.map((l: Loan): KW => ({ k: l.k, r: l.r, m: l.m, cat: "daily" })),
  ...KWORD_RAW.split("\n").map((l: string): KW => {
    const [cat, k, r, m] = l.split("|") as [string, string, string, string];
    return { k, r, m, cat };
  }),
];
const KW_CATS: [string, string][] = [["all", "全部"], ["daily", "日常外來語"], ["menu", "菜單"], ["place", "國名・地名"]];
function normRoma(s: string): string {
  let x = s.toLowerCase().normalize("NFC").replace(/[āâ]/g, "a").replace(/[īî]/g, "i").replace(/[ūû]/g, "u").replace(/[ēê]/g, "e").replace(/[ōô]/g, "o").replace(/[\s\-'’・ー]/g, "");
  x = x.replace(/sy/g, "sh").replace(/ty/g, "ch").replace(/[jz]y/g, "j").replace(/si/g, "shi").replace(/ti/g, "chi").replace(/tu/g, "tsu").replace(/hu/g, "fu").replace(/zi/g, "ji").replace(/m(?=[bp])/g, "n");
  return x.replace(/ou/g, "o").replace(/([aeiou])\1+/g, "$1");
}
function kwQ(pool: KW[], m: "r" | "m"): Q {
  const w = pick(pool.length ? pool : KWORDS);
  const others = shuffle(KWORDS.filter((x: KW) => x.k !== w.k));
  const same = others.filter((x: KW) => x.cat === w.cat);
  const exp = `${w.k}（${w.r}）＝${w.m}\n長音「ー」→ 母音拉長；小「ッ」→ 下一個子音重複；小「ャュョ」和前一個字合成一拍。`;
  if (m === "m") {
    const ds = uniq([...same, ...others].map((x: KW) => x.m)).filter((x: string) => x !== w.m);
    return { id: `kana:kw:${w.k}:m`, sec: "kana", tag: "片假名讀詞：選中文意思", prompt: w.k, ja: true, big: true, ...mc(w.m, ds), tts: w.k, ttsAfter: true, exp, kana: [] };
  }
  const ds2 = uniq([...shuffle(romaVariants(w.r)), ...same.map((x: KW) => x.r), ...others.map((x: KW) => x.r)]).filter((x: string) => x !== w.r);
  return { id: `kana:kw:${w.k}:r`, sec: "kana", tag: "片假名讀詞：選羅馬字", prompt: w.k, ja: true, big: true, ...mc(w.r, ds2), tts: w.k, ttsAfter: true, exp, kana: [] };
}
function KataType(props: { pool: KW[] }) {
  const t = useGrokTheme();
  const pool = props.pool.length ? props.pool : KWORDS;
  const [w, setW] = useState<KW>(() => pick(pool));
  const [v, setV] = useState("");
  const [res, setRes] = useState<boolean | null>(null);
  const [sc, setSc] = useState({ c: 0, n: 0 });
  const ref = useRef<HTMLInputElement | null>(null);
  const go = () => {
    if (res !== null) {
      const rest = pool.filter((x: KW) => x.k !== w.k);
      setW(pick(rest.length ? rest : pool));
      setV("");
      setRes(null);
      window.setTimeout(() => ref.current?.focus(), 0);
      return;
    }
    if (!v.trim()) return;
    const ok = normRoma(v) === normRoma(w.r);
    setRes(ok);
    setSc((s: { c: number; n: number }) => ({ c: s.c + (ok ? 1 : 0), n: s.n + 1 }));
    record({ id: `kana:kw:${w.k}:t`, sec: "kana", tag: "片假名讀詞：打羅馬字", prompt: `片假名讀詞（打羅馬字）：${w.k}`, options: [w.r], answer: 0, exp: `${w.k}（${w.r}）＝${w.m}` }, ok);
    speak(w.k);
  };
  return (
    <Card>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, marginBottom: 8 }}>
        <span style={{ color: t.text.accent, fontWeight: 600 }}>片假名讀詞：看字打羅馬字</span>
        <span style={{ color: t.text.secondary }}>本輪 {sc.c}/{sc.n}</span>
      </div>
      <div lang="ja" style={{ fontFamily: JA_FONT, fontSize: 44, textAlign: "center", margin: "6px 0 12px", wordBreak: "break-all" }}>{w.k}</div>
      <div style={{ display: "flex", gap: 8 }}>
        <input
          ref={ref}
          value={v}
          aria-label="輸入羅馬字讀音"
          placeholder="例：kōhī 或 koohii"
          autoCapitalize="off"
          autoComplete="off"
          spellCheck={false}
          onChange={(e: ChangeEvent<HTMLInputElement>) => setV(e.target.value)}
          onKeyDown={(e: { key: string; preventDefault: () => void }) => {
            if (e.key === "Enter") {
              e.preventDefault();
              go();
            }
          }}
          style={{ font: "inherit", fontSize: 17, flex: 1, minWidth: 0, padding: "10px 12px", borderRadius: 10, border: `1px solid ${t.border.default}`, background: t.bg.base, color: t.text.primary }}
        />
        <Btn kind="primary" label={res === null ? "確認" : "下一個 →"} onClick={go} />
      </div>
      {res !== null ? (
        <div role="status" aria-live="polite" style={{ marginTop: 12, padding: 12, borderRadius: 10, background: res ? t.fill.successSubtle : t.fill.dangerSubtle, borderLeft: `4px solid ${res ? t.text.success : t.text.danger}` }}>
          <div style={{ fontWeight: 600, color: t.text.primary }}>{res ? "✓ 正確！" : `✗ 正確答案：${w.r}`}</div>
          <div style={{ fontSize: 14, marginTop: 4 }}>{w.k}（{w.r}）＝{w.m}</div>
        </div>
      ) : null}
      <div style={{ marginTop: 10 }}>
        <Note>長音可以打成重複母音或省略（kōhī＝koohii＝kohi），シ／チ／ツ／フ 也可以打 si／ti／tu／hu。按 Enter 送出、再按 Enter 下一個。</Note>
      </div>
    </Card>
  );
}
function KataRead() {
  const [cat, setCat] = useState("all");
  const [m, setM] = useState<"r" | "m" | "type">("r");
  const pool = useMemo(() => KWORDS.filter((w: KW) => cat === "all" || w.cat === cat), [cat]);
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Card>
        <div style={{ display: "grid", gap: 10 }}>
          <Chips small value={cat} onChange={setCat} options={KW_CATS.map(([k, l]: [string, string]): [string, string] => [k, `${l} ${k === "all" ? KWORDS.length : KWORDS.filter((w: KW) => w.cat === k).length}`])} />
          <Chips small value={m} onChange={setM} options={[["r", "選羅馬字"], ["m", "選中文意思"], ["type", "⌨️ 打羅馬字"]]} />
          <Note>整個單字一起讀：日常外來語、餐廳菜單、國名與城市名。先在心裡唸出來再作答，答完會播放發音。</Note>
        </div>
      </Card>
      {m === "type" ? <KataType key={cat} pool={pool} /> : <QuizRunner key={`${cat}|${m}`} gen={() => kwQ(pool, m)} />}
    </div>
  );
}
const LOOK: Record<string, string> = { シ: "ツ", ツ: "シ", ソ: "ン", ン: "ソ", ク: "ケタ", ケ: "ク", タ: "ク", ナ: "メ", メ: "ナヌ", ヌ: "スメ", ス: "ヌ", ウ: "ワ", ワ: "ウフ", フ: "ワ", チ: "テ", テ: "チ", コ: "ユロ", ユ: "コヨ", ロ: "コ", ヨ: "ユ", ラ: "ヲ", ヲ: "ラ", ル: "レ", レ: "ル", ア: "マ", マ: "ア", セ: "サヤ", サ: "セ", ヤ: "セ", キ: "モ", モ: "キ", さ: "きち", き: "さ", ち: "さら", ら: "ち", ぬ: "め", め: "ぬ", ね: "れわ", れ: "ねわ", わ: "ねれ", る: "ろ", ろ: "る", は: "ほけ", ほ: "は", け: "は", い: "こり", こ: "い", り: "い", あ: "お", お: "あ", ま: "も", も: "ま", し: "つ", つ: "し", た: "な", な: "た" };
const DAK = "かが きぎ くぐ けげ こご さざ しじ すず せぜ そぞ ただ ちぢ つづ てで とど はばぱ ひびぴ ふぶぷ へべぺ ほぼぽ".split(" ");
function toHiraS(s: string): string {
  return s.replace(/[\u30a1-\u30f6]/g, (c: string) => String.fromCharCode(c.charCodeAt(0) - 0x60));
}
function altsOf(c: string): string[] {
  const kat = /[\u30a1-\u30f6]/.test(c);
  const h = kat ? toHiraS(c) : c;
  const g = DAK.find((x: string) => x.includes(h));
  const dk = g ? Array.from(g).filter((x: string) => x !== h).map((x: string) => (kat ? toKata(x) : x)) : [];
  return [...Array.from(LOOK[c] ?? ""), ...dk];
}
function perturb(w: string, script: "h" | "k"): string[] {
  const cs = Array.from(w);
  const out: string[] = [];
  shuffle(cs.map((_: string, i: number) => i)).forEach((i: number) => {
    altsOf(cs[i] ?? "").forEach((a: string) => {
      const x = [...cs];
      x[i] = a;
      out.push(x.join(""));
    });
  });
  const pool = ALL_KANA.map((k: Kana) => (script === "h" ? k.h : k.k)).filter((c: string) => c.length === 1);
  for (let n = 0; n < 12; n++) {
    const i = Math.floor(Math.random() * cs.length);
    if (cs[i] === "ー") continue;
    const x = [...cs];
    x[i] = pick(pool);
    out.push(x.join(""));
  }
  return uniq(out).filter((x: string) => x !== w);
}
const HIRA_WORDS: Vocab[] = VOCAB.filter((v: Vocab) => /^[\u3041-\u3096]{3,7}$/.test(v.r));
function convQ(): Q {
  if (Math.random() < 0.6) {
    const w = pick(KWORDS);
    const hira = toHiraS(w.k);
    return { id: `kana:conv:${w.k}`, sec: "kana", tag: "平假名 → 片假名（整個單字）", prompt: hira, big: true, ja: true, optJa: true, ...mc(w.k, perturb(w.k, "k")), tts: w.k, ttsAfter: true, exp: `${hira} → ${w.k}（${w.r}）＝${w.m}\n外來語平常寫成片假名；這裡先用平假名寫出讀音，練習逐字對應（ー 照抄）。`, kana: [] };
  }
  const v = pick(HIRA_WORDS);
  const kata = toKata(v.r);
  return { id: `kana:conv:${v.r}`, sec: "kana", tag: "片假名 → 平假名（整個單字）", prompt: kata, big: true, ja: true, optJa: true, ...mc(v.r, perturb(v.r, "h")), tts: v.r, ttsAfter: true, exp: `${kata} → ${v.r}（${v.w}）＝${v.m}`, kana: [] };
}
function BossRound() {
  const t = useGrokTheme();
  const db = useDB();
  const HP = 15;
  const [st, setSt] = useState({ hp: HP, lives: 3, n: 0 });
  const [phase, setPhase] = useState<"intro" | "fight" | "win" | "lose">("intro");
  const [tries, setTries] = useState(0);
  useEffect(() => {
    if (phase !== "fight") return undefined;
    if (st.hp > 0 && st.lives > 0) return undefined;
    const win = st.hp <= 0;
    const id = window.setTimeout(() => {
      if (win) {
        DB.best = { ...DB.best, boss: (DB.best.boss ?? 0) + 1 };
        commit();
      }
      setPhase(win ? "win" : "lose");
    }, 1200);
    return () => window.clearTimeout(id);
  }, [st, phase]);
  const gen = (): Q => {
    const r = Math.random();
    if (r < 0.55) return { ...confQ("k"), tag: "👾 魔王關：片假名形近字" };
    if (r < 0.75) return { ...confQ("h"), tag: "👾 魔王關：平假名形近字" };
    const pool = poolOf(ROWS.map((x: Row) => x.id), "kata");
    return { ...kanaQ(pool, Math.random() < 0.5 ? "k2r" : "r2k"), tag: "👾 魔王關：全部行混合片假名" };
  };
  const start = () => {
    setSt({ hp: HP, lives: 3, n: 0 });
    setTries((n: number) => n + 1);
    setPhase("fight");
  };
  const hearts = "❤️".repeat(Math.max(0, st.lives)) + "🤍".repeat(Math.max(0, 3 - st.lives));
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Card title="👾 形近字魔王關（全部行混合）">
        {phase === "intro" ? (
          <div style={{ display: "grid", gap: 10 }}>
            <Note>魔王有 {HP} 點血，你有 3 顆心。題目從所有行的「長得像」的假名出（シツ・ソン・ナメ・ウワ・コユ・ぬめ・ねれわ…），片假名為主。答對打掉 1 點血，答錯扣 1 顆心。答錯的字會自動進複習佇列。</Note>
            <div>
              <Btn kind="primary" label="⚔️ 開始挑戰" onClick={start} />
            </div>
            <span style={{ fontSize: 13, color: t.text.secondary }}>已打倒魔王 {db.best.boss ?? 0} 次</span>
          </div>
        ) : (
          <div style={{ display: "grid", gap: 8 }}>
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 14, gap: 8, flexWrap: "wrap" }}>
              <span>👾 魔王 HP {Math.max(0, st.hp)}/{HP}</span>
              <span aria-label={`剩下 ${st.lives} 顆心`}>{hearts}</span>
            </div>
            <Bar v={Math.max(0, st.hp) / HP} color={t.text.danger} label="魔王剩餘血量" />
            {phase === "win" ? (
              <div role="status" style={{ display: "grid", gap: 8, marginTop: 6 }}>
                <div style={{ fontSize: 22, fontWeight: 600, color: t.text.success }}>🏆 打倒魔王！（{st.n} 題、剩 {st.lives} 顆心）</div>
                <div>
                  <Btn kind="primary" label="再挑戰一次" onClick={start} />
                </div>
              </div>
            ) : null}
            {phase === "lose" ? (
              <div role="status" style={{ display: "grid", gap: 8, marginTop: 6 }}>
                <div style={{ fontSize: 20, fontWeight: 600, color: t.text.danger }}>💀 挑戰失敗：魔王還剩 {st.hp} 點血</div>
                <Note>先到「易混淆字」或「⏰ 複習佇列」把答錯的字練熟，再回來挑戰！</Note>
                <div>
                  <Btn kind="primary" label="再挑戰一次" onClick={start} />
                </div>
              </div>
            ) : null}
          </div>
        )}
      </Card>
      {phase === "fight" ? (
        <QuizRunner
          key={`boss${tries}`}
          gen={gen}
          onResult={(q: Q, ok: boolean) => {
            if (q.kana) bumpWeak(q.kana, ok);
            setSt((s: { hp: number; lives: number; n: number }) => ({ hp: ok ? s.hp - 1 : s.hp, lives: ok ? s.lives : s.lives - 1, n: s.n + 1 }));
          }}
        />
      ) : null}
    </div>
  );
}
function medal(v: number): string {
  return v >= 0.95 ? "🥇" : v >= 0.85 ? "🥈" : v >= 0.7 ? "🥉" : "";
}
function rowMastery(r: Row, scr: "h" | "k"): number {
  const cells = r.cells.filter((c: Kana | null): c is Kana => c !== null);
  return cells.reduce((s: number, k: Kana) => s + mastery(scr === "h" ? k.h : k.k), 0) / Math.max(1, cells.length);
}
function BadgeWall() {
  const t = useGrokTheme();
  useDB();
  const col = (scr: "h" | "k") => ROWS.map((r: Row) => ({ r, m: medal(rowMastery(r, scr)) }));
  const all = [...col("h"), ...col("k")];
  const cnt = (m: string) => all.filter((x: { r: Row; m: string }) => x.m === m).length;
  const got = all.filter((x: { r: Row; m: string }) => x.m).length;
  return (
    <Card title={`🏅 行徽章 ${got}/${all.length}`}>
      <div style={{ display: "flex", gap: 16, flexWrap: "wrap", fontSize: 14 }}>
        <span>🥇 {cnt("🥇")}</span>
        <span>🥈 {cnt("🥈")}</span>
        <span>🥉 {cnt("🥉")}</span>
      </div>
      {(["h", "k"] as ("h" | "k")[]).map((scr: "h" | "k") => (
        <div key={scr} style={{ marginTop: 8 }}>
          <div style={{ fontSize: 12, color: t.text.secondary, marginBottom: 4 }}>{scr === "h" ? "平假名" : "片假名"}</div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
            {col(scr).map(({ r, m }: { r: Row; m: string }) => (
              <span key={r.id} aria-label={`${scr === "h" ? "平假名" : "片假名"} ${r.name}：${m ? "已得到徽章 " + m : "尚未得到"}`} style={{ border: `1px solid ${m ? t.text.success : t.border.subtle}`, borderRadius: 8, padding: "2px 8px", fontSize: 13, fontFamily: JA_FONT, color: m ? t.text.primary : t.text.secondary }}>
                {m || "🔒"} {scr === "k" ? toKata(r.name) : r.name}
              </span>
            ))}
          </div>
        </div>
      ))}
      <div style={{ marginTop: 8 }}>
        <Note>一行的平均掌握度達 70% 得 🥉、85% 得 🥈、95% 得 🥇（每個字至少答 3 次才會滿分；變成弱點會掉分，練回來就會恢復）。</Note>
      </div>
    </Card>
  );
}
function SrsSpread() {
  const t = useGrokTheme();
  const db = useDB();
  const now = Date.now();
  const B: [string, number][] = [["現在", 0], ["1 小時內", 3600e3], ["1–4 小時", 4 * 3600e3], ["4–12 小時", 12 * 3600e3], ["12–24 小時", 86400e3], ["明天以後", Infinity]];
  const cnt: number[] = B.map(() => 0);
  Object.keys(db.srs).forEach((c: string) => {
    const d = (db.srs[c]?.due ?? 0) - now;
    let i = d <= 0 ? 0 : B.findIndex((b: [string, number], j: number) => j > 0 && d <= b[1]);
    if (i < 0) i = B.length - 1;
    cnt[i] = (cnt[i] ?? 0) + 1;
  });
  const mx = Math.max(1, ...cnt);
  return (
    <div style={{ margin: "4px 0 10px" }}>
      <div style={{ fontSize: 12, color: t.text.secondary, marginBottom: 4 }}>接下來的複習分布（一天內分散到期）</div>
      <div style={{ display: "grid", gap: 4 }}>
        {B.map((b: [string, number], i: number) => (
          <div key={b[0]} style={{ display: "grid", gridTemplateColumns: "84px 1fr 32px", gap: 8, alignItems: "center", fontSize: 12 }}>
            <span>{b[0]}</span>
            <Bar v={(cnt[i] ?? 0) / mx} color={i === 0 ? t.text.danger : t.text.accent} label={`${b[0]} ${cnt[i] ?? 0} 個`} />
            <span style={{ textAlign: "right", color: t.text.secondary }}>{cnt[i] ?? 0}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
/* ============ 今日最弱 5 字・單字聽寫 ============ */
function NARROW(): boolean {
  return typeof window !== "undefined" && window.innerWidth < 700;
}
function returningUser(): boolean {
  return Object.values(DB.stats).some((x: { c: number; w: number }) => x.c + x.w > 0);
}
function dayHash(s: string): number {
  return (Array.from(s + today()).reduce((h: number, ch: string) => (h * 31 + ch.charCodeAt(0)) % 9973, 7) % 1000) / 1000;
}
function weakest5(): KItem[] {
  const all = poolOf(ROWS.map((r: Row) => r.id), "mix");
  const sc = (x: KItem): number => weakScore(x.c) * 10 + (DB.ks[x.c]?.n ? (1 - mastery(x.c)) * 5 : 0) + (x.scr === "k" ? 0.5 : 0) + (confOf(x.c) ? 0.3 : 0) + dayHash(x.c) * 0.25;
  return [...all].sort((a: KItem, b: KItem) => sc(b) - sc(a)).slice(0, 5);
}
function Weak5Drill() {
  const t = useGrokTheme();
  const [k, setK] = useState(0);
  const five = useMemo(() => weakest5(), [k]);
  const gen = (): Q => ({ ...kanaQ(five, Math.random() < 0.5 ? "k2r" : "r2k"), tag: "🎯 今日最弱 5 字" });
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Card title="🎯 今日最弱的 5 個假名">
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
          {five.map((x: KItem) => (
            <span key={x.c} lang="ja" style={{ fontFamily: JA_FONT, fontSize: 24, border: `1px solid ${t.border.default}`, borderRadius: 8, padding: "0 12px" }}>
              {x.c}
            </span>
          ))}
          <Btn small label="重新挑選" onClick={() => setK((n: number) => n + 1)} />
        </div>
        <div style={{ marginTop: 8 }}>
          <Note>依答錯紀錄與掌握度挑出（還沒練過的話，先從片假名和易混淆字開始）。一輪 10 題，答錯的字會排進「⏰ 複習佇列」。</Note>
        </div>
      </Card>
      <QuizRunner key={`w5${k}`} gen={gen} total={10} onResult={(q: Q, ok: boolean) => { if (q.kana && q.kana.length) bumpWeak(q.kana, ok); }} />
    </div>
  );
}
type DW = { w: string; scr: "h" | "k"; r: string; m: string };
const DICT_WORDS: DW[] = [
  ...HIRA_WORDS.map((v: Vocab): DW => ({ w: v.r, scr: "h", r: romaOf(v.r), m: v.w === v.r ? v.m : `${v.w}：${v.m}` })),
  ...KWORDS.map((k: KW): DW => ({ w: k.k, scr: "k", r: k.r, m: k.m })),
];
function soundKey(s: string): string {
  return toHiraS(s)
    .replace(/づ/g, "ず")
    .replace(/ぢ/g, "じ")
    .replace(/を/g, "お")
    .replace(/([えけせてねへめれげぜでべぺ])い/g, "$1え")
    .replace(/([おこそとのほもよろごぞどぼぽょ])う/g, "$1お");
}
function dictPool(scr: "h" | "k" | "mix"): DW[] {
  return DICT_WORDS.filter((d: DW) => scr === "mix" || d.scr === scr);
}
function dictQ(scr: "h" | "k" | "mix"): Q {
  const w = pick(dictPool(scr));
  const ds = perturb(w.w, w.scr).filter((x: string) => soundKey(x) !== soundKey(w.w));
  return { id: `kana:dict:${w.w}`, sec: "kana", tag: w.scr === "h" ? "🎧 聽寫：平假名單字" : "🎧 聽寫：片假名單字", prompt: "🎧 只聽聲音，選出聽到的單字（按 🔊 或 R 鍵重播）", optJa: true, ...mc(w.w, ds), tts: w.w, autoPlay: true, exp: `${w.w}（${w.r}）＝${w.m}`, kana: [] };
}
function DictType(props: { scr: "h" | "k" | "mix" }) {
  const t = useGrokTheme();
  const pool = dictPool(props.scr);
  const [w, setW] = useState<DW>(() => pick(pool));
  const [v, setV] = useState("");
  const [res, setRes] = useState<null | "ok" | "roma" | "script" | "ng">(null);
  const [sc, setSc] = useState({ c: 0, n: 0 });
  const ref = useRef<HTMLInputElement | null>(null);
  useEffect(() => {
    const id = window.setTimeout(() => speak(w.w), 250);
    return () => window.clearTimeout(id);
  }, [w]);
  const go = () => {
    if (res !== null) {
      const rest = pool.filter((x: DW) => x.w !== w.w);
      setW(pick(rest.length ? rest : pool));
      setV("");
      setRes(null);
      window.setTimeout(() => ref.current?.focus(), 0);
      return;
    }
    const a = v.trim();
    if (!a) return;
    let r: "ok" | "roma" | "script" | "ng" = "ng";
    if (a === w.w) r = "ok";
    else if (/^[a-zA-Zāīūēō\s'-]+$/.test(a) && normRoma(a) === normRoma(w.r)) r = "roma";
    else if (toHiraS(a) === toHiraS(w.w)) r = "script";
    const ok = r === "ok" || r === "roma";
    setRes(r);
    setSc((s: { c: number; n: number }) => ({ c: s.c + (ok ? 1 : 0), n: s.n + 1 }));
    record({ id: `kana:dict:${w.w}:t`, sec: "kana", tag: "🎧 單字聽寫（打字）", prompt: `聽寫：${w.r}（${w.m}）`, options: [w.w], answer: 0, exp: `${w.w}（${w.r}）＝${w.m}` }, ok);
  };
  const msg = res === "ok" ? "✓ 正確！" : res === "roma" ? "✓ 正確！（讀音對了；建議用日文輸入法打出假名）" : res === "script" ? `✗ 讀音對了，但要寫成${w.scr === "k" ? "片假名" : "平假名"}：${w.w}` : `✗ 正確答案：${w.w}`;
  const good = res === "ok" || res === "roma";
  return (
    <Card>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, marginBottom: 8 }}>
        <span style={{ color: t.text.accent, fontWeight: 600 }}>🎧 單字聽寫：聽聲音，打出假名</span>
        <span style={{ color: t.text.secondary }}>本輪 {sc.c}/{sc.n}</span>
      </div>
      <div style={{ display: "flex", gap: 8, justifyContent: "center", margin: "6px 0 12px" }}>
        <Btn label="🔊 再聽一次" onClick={() => speak(w.w)} />
        <Btn label="🐢 慢速" onClick={() => speak(w.w, 0.6)} />
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <input
          ref={ref}
          value={v}
          lang="ja"
          aria-label="輸入聽到的假名"
          placeholder={props.scr === "h" ? "例：ありがとう" : props.scr === "k" ? "例：コーヒー" : "平假名或片假名"}
          autoCapitalize="off"
          autoComplete="off"
          spellCheck={false}
          onChange={(e: ChangeEvent<HTMLInputElement>) => setV(e.target.value)}
          onKeyDown={(e: { key: string; preventDefault: () => void; nativeEvent?: { isComposing?: boolean } }) => {
            if (e.key === "Enter" && !e.nativeEvent?.isComposing) {
              e.preventDefault();
              go();
            }
          }}
          style={{ font: "inherit", fontFamily: JA_FONT, fontSize: 20, flex: 1, minWidth: 0, padding: "10px 12px", borderRadius: 10, border: `1px solid ${t.border.default}`, background: t.bg.base, color: t.text.primary }}
        />
        <Btn kind="primary" label={res === null ? "確認" : "下一個 →"} onClick={go} />
      </div>
      {res !== null ? (
        <div role="status" aria-live="polite" style={{ marginTop: 12, padding: 12, borderRadius: 10, background: good ? t.fill.successSubtle : t.fill.dangerSubtle, borderLeft: `4px solid ${good ? t.text.success : t.text.danger}` }}>
          <div lang="ja" style={{ fontWeight: 600, color: t.text.primary }}>{msg}</div>
          <div lang="ja" style={{ fontSize: 14, marginTop: 4 }}>{w.w}（{w.r}）＝{w.m}</div>
        </div>
      ) : null}
      <div style={{ marginTop: 10 }}>
        <Note>用手機或電腦的日文輸入法打出假名（片假名單字要打片假名）。一時沒有日文輸入法，也可以打羅馬字。按 Enter 送出、再按 Enter 下一個。</Note>
      </div>
    </Card>
  );
}
function KanaDictation() {
  const [scr, setScr] = useState<"h" | "k" | "mix">("k");
  const [m, setM] = useState<"pick" | "type">("pick");
  const gen = useMemo(() => () => dictQ(scr), [scr]);
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Card>
        <div style={{ display: "grid", gap: 8 }}>
          <Chips small value={scr} onChange={setScr} options={[["k", `片假名單字 ${dictPool("k").length}`], ["h", `平假名單字 ${dictPool("h").length}`], ["mix", "混合"]]} />
          <Chips small value={m} onChange={setM} options={[["pick", "聽音選寫法"], ["type", "⌨️ 聽音打假名"]]} />
          <Note>只聽聲音、不看字：選項都是只差一兩個假名的「形近」或「音近」寫法（發音完全相同的寫法已排除）。</Note>
        </div>
      </Card>
      {m === "pick" ? <QuizRunner key={`dict${scr}`} gen={gen} /> : <DictType key={`dt${scr}`} scr={scr} />}
    </div>
  );
}
type KMode = "table" | "quiz" | "voice" | "len" | "ext" | "type" | "speed" | "klisten" | "conf" | "mnemo" | "match" | "loan" | "srs" | "weak" | "dash" | "kword" | "conv" | "boss" | "weak5" | "dict";
let KANA_START: KMode | null = null;
function KanaTab() {
  const t = useGrokTheme();
  const [mode, setMode] = useState<KMode>(() => KANA_START ?? (returningUser() ? "quiz" : "table"));
  const [vs, setVs] = useState<"listen" | "see">("listen");
  useEffect(() => {
    KANA_START = null;
  }, []);
  const lb = { font: "inherit", cursor: "pointer", background: "transparent", border: "none", color: t.text.primary, padding: 0, fontFamily: JA_FONT } as const;
  const [script, setScript] = useState<Script>("kata");
  const [dir, setDir] = useState<"k2r" | "r2k">("k2r");
  const [rows, setRows] = useState<string[]>(["a", "ka", "sa", "ta", "na"]);
  const [weakOnly, setWeakOnly] = useState(false);
  const [confW, setConfW] = useState<"all" | "h" | "k">("all");
  const [mm, setMm] = useState<"mc" | "game">("mc");
  const [lm, setLm] = useState<"m" | "r" | "mix">("mix");
  const db = useDB();
  const pool2: KItem[] = useMemo(() => poolOf(rows, script), [rows, script]);

  const pool: KItem[] = useMemo(() => {
    if (weakOnly) {
      const all = poolOf(ROWS.map((r: Row) => r.id), "mix");
      return all.filter((x: KItem) => weakScore(x.c) > 0);
    }
    return poolOf(rows, script);
    // eslint-disable-next-line
  }, [rows, script, weakOnly, weakOnly ? 0 : 1]);
  const onKana = (q: Q, ok: boolean) => {
    if (q.kana && q.kana.length) bumpWeak(q.kana, ok);
  };
  const weakCount = Object.keys(db.weak).filter((c: string) => weakScore(c) > 0).length;
  const dueN = srsDue().length;

  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Chips
        small
        scroll={NARROW()}
        value={mode}
        onChange={setMode}
        options={[
          ["table", "五十音表"],
          ["quiz", "認讀測驗"],
          ["weak5", "🎯 最弱 5 字"],
          ["voice", "濁音・拗音"],
          ["len", "促音・長音"],
          ["ext", "外來音 ファ・ティ"],
          ["klisten", "聽音選假名"],
          ["dict", "🎧 單字聽寫"],
          ["type", "打字練習"],
          ["speed", "60秒挑戰"],
          ["conf", "易混淆字"],
          ["mnemo", "片假名記憶法"],
          ["match", "平↔片配對"],
          ["loan", "外來語片假名"],
          ["srs", `⏰ 複習佇列${dueN ? "（" + dueN + "）" : ""}`],
          ["weak", `弱點假名${weakCount ? "（" + weakCount + "）" : ""}`],
          ["dash", "📊 掌握度"],
          ["kword", "片假名讀詞"],
          ["conv", "平↔片 單字轉換"],
          ["boss", "👾 魔王關"],
        ]}
      />
      {mode === "table" ? <KanaTable /> : null}
      {mode === "quiz" ? (
        <div style={{ display: "grid", gap: 12 }}>
          <Card>
            <div style={{ display: "grid", gap: 10 }}>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 6, alignItems: "center" }}>
                <Chips small value={script} onChange={(v: Script) => { setScript(v); setWeakOnly(false); }} options={[["hira", "平假名"], ["kata", "片假名"], ["mix", "混合"]]} />
                <Btn small on={weakOnly} label={weakOnly ? "✓ 只練弱點" : "只練弱點"} onClick={() => setWeakOnly(!weakOnly)} />
                <Chips small value={dir} onChange={setDir} options={[["k2r", "看假名選讀音"], ["r2k", "看讀音選假名"]]} />
              </div>
              {weakOnly ? <Note>只出你答錯過、還沒練回來的假名（不限行）。</Note> : <RowPicker rows={rows} onChange={setRows} kata={script === "kata"} />}
            </div>
          </Card>
          {pool.length ? (
            <QuizRunner key={`${script}|${dir}|${rows.join(",")}|${weakOnly}`} gen={() => kanaQ(pool, dir)} onResult={onKana} />
          ) : (
            <Card>
              <Note>{weakOnly ? "目前沒有弱點假名 🎉 先去做幾題一般測驗吧。" : "請至少選一行。"}</Note>
            </Card>
          )}
        </div>
      ) : null}
      {mode === "conf" ? (
        <div style={{ display: "grid", gap: 12 }}>
          <Chips value={confW} onChange={setConfW} options={[["all", "全部"], ["h", "平假名組"], ["k", "片假名組"]]} />
          <QuizRunner key={confW} gen={() => confQ(confW)} onResult={onKana} />
          <Card title="易混淆字對照表">
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))", gap: 10 }}>
              {CONF.map((g: { g: string[]; tip: string }) => (
                <div key={g.g.join("")} style={{ border: `1px solid ${t.border.subtle}`, borderRadius: 10, padding: 10 }}>
                  <div style={{ display: "flex", gap: 10, marginBottom: 6 }}>
                    {g.g.map((c: string) => (
                      <button key={c} type="button" onClick={() => speak(c)} style={{ font: "inherit", cursor: "pointer", background: "transparent", border: "none", color: t.text.primary, padding: 0, textAlign: "center" }}>
                        <div lang="ja" style={{ fontFamily: JA_FONT, fontSize: 30, lineHeight: 1.1 }}>{c}</div>
                        <div style={{ fontSize: 11, color: t.text.secondary }}>{ROMA[c] ?? ""}</div>
                      </button>
                    ))}
                  </div>
                  <div style={{ fontSize: 13, lineHeight: 1.6, color: t.text.secondary }}>{g.tip}</div>
                </div>
              ))}
            </div>
          </Card>
        </div>
      ) : null}
      {mode === "match" ? (
        <div style={{ display: "grid", gap: 12 }}>
          <Card>
            <div style={{ display: "grid", gap: 10 }}>
              <Chips value={mm} onChange={setMm} options={[["mc", "選擇題"], ["game", "翻牌配對遊戲"]]} />
              <RowPicker rows={rows} onChange={setRows} kata={false} />
            </div>
          </Card>
          {rows.length === 0 ? (
            <Card>
              <Note>請至少選一行。</Note>
            </Card>
          ) : mm === "mc" ? (
            <QuizRunner key={rows.join(",")} gen={() => matchQ(rows)} onResult={onKana} />
          ) : (
            <MatchGame key={rows.join(",")} rows={rows} />
          )}
        </div>
      ) : null}
      {mode === "loan" ? (
        <div style={{ display: "grid", gap: 12 }}>
          <Chips value={lm} onChange={setLm} options={[["mix", "混合"], ["m", "選意思"], ["r", "選讀音"]]} />
          <QuizRunner key={lm} gen={() => loanQ(lm)} />
          <Card title={`外來語清單（${LOANS.length}）`}>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))", gap: 8 }}>
              {LOANS.map((w: Loan) => (
                <button key={w.k} type="button" onClick={() => speak(w.k)} style={{ font: "inherit", cursor: "pointer", textAlign: "left", padding: "8px 10px", borderRadius: 8, border: `1px solid ${t.border.subtle}`, background: t.bg.base, color: t.text.primary }}>
                  <div lang="ja" style={{ fontFamily: JA_FONT, fontSize: 17 }}>{w.k}</div>
                  <div style={{ fontSize: 12, color: t.text.secondary }}>
                    {w.r}・{w.m}
                  </div>
                </button>
              ))}
            </div>
          </Card>
        </div>
      ) : null}
      {mode === "type" || mode === "speed" || mode === "klisten" ? (
        <Card>
          <div style={{ display: "grid", gap: 10 }}>
            <Chips value={script} onChange={(v: Script) => setScript(v)} options={[["hira", "平假名"], ["kata", "片假名"], ["mix", "混合"]]} />
            <RowPicker rows={rows} onChange={setRows} kata={script === "kata"} />
          </div>
        </Card>
      ) : null}
      {mode === "type" ? (
        pool2.length ? (
          <TypingDrill key={`${script}|${rows.join(",")}`} pool={pool2} />
        ) : (
          <Card>
            <Note>請至少選一行。</Note>
          </Card>
        )
      ) : null}
      {mode === "speed" ? (
        pool2.length ? (
          <SpeedRound key={`${script}|${rows.join(",")}`} pool={pool2} bestKey={`${script}|${rows.slice().sort().join(",")}`} />
        ) : (
          <Card>
            <Note>請至少選一行。</Note>
          </Card>
        )
      ) : null}
      {mode === "klisten" ? <KanaListen pool={pool2} k={`${script}|${rows.join(",")}`} /> : null}
      {mode === "voice" ? (
        <div style={{ display: "grid", gap: 12 }}>
          <Card>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 10, alignItems: "center" }}>
              <Chips value={script} onChange={setScript} options={[["hira", "平假名"], ["kata", "片假名"], ["mix", "混合"]]} />
              <span aria-hidden="true" style={{ color: t.text.secondary }}>|</span>
              <Chips value={vs} onChange={setVs} options={[["listen", "🎧 聽音辨別"], ["see", "看讀音選字"]]} />
            </div>
            <div style={{ marginTop: 8 }}>
              <Note>專練只差一個點、一個圈或大小字的組合：カ／ガ、ハ／バ／パ、キャ／キヤ／ギャ、シュ／ジュ…</Note>
            </div>
          </Card>
          <QuizRunner key={`v|${script}|${vs}`} gen={() => voiceQ(script, vs === "listen")} onResult={onKana} />
        </div>
      ) : null}
      {mode === "len" ? (
        <div style={{ display: "grid", gap: 12 }}>
          <QuizRunner key="len" gen={lenQ} onResult={onKana} />
          <Card title="促音（っ／ッ）・長音（ー／う）・拗音大小字 對照">
            <Note>日語每一拍都算數：おばさん（阿姨，4 拍）≠ おばあさん（奶奶，5 拍）。促音是停頓一拍，長音是拉長一拍。點字聽發音，比較兩者差別。</Note>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))", gap: 6, marginTop: 10 }}>
              {LEN.map((p: LenPair) => (
                <div key={p.a} style={{ display: "flex", gap: 8, alignItems: "baseline", flexWrap: "wrap", border: `1px solid ${t.border.subtle}`, borderRadius: 8, padding: "4px 8px", fontSize: 13 }}>
                  <button type="button" aria-label={`播放 ${p.a}`} onClick={() => speak(p.a)} style={{ ...lb, fontSize: 18 }} lang="ja">{p.a}</button>
                  <span style={{ color: t.text.secondary }}>{p.ma}</span>
                  <span style={{ color: t.text.tertiary }}>／</span>
                  <button type="button" aria-label={`播放 ${p.b}`} onClick={() => speak(p.b)} style={{ ...lb, fontSize: 18 }} lang="ja">{p.b}</button>
                  <span style={{ color: t.text.secondary }}>{p.mb}</span>
                </div>
              ))}
            </div>
          </Card>
        </div>
      ) : null}
      {mode === "ext" ? (
        <div style={{ display: "grid", gap: 12 }}>
          <QuizRunner key="ext" gen={extQ} onResult={onKana} />
          <Card title={`外來音（特殊音）對照表・${EXT.length} 個`}>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))", gap: 8 }}>
              {EXT.map((e: Ext) => (
                <button key={e.k} type="button" aria-label={`${e.k} ${e.r}，例：${e.w}`} onClick={() => speak(e.w)} style={{ font: "inherit", cursor: "pointer", textAlign: "left", border: `1px solid ${t.border.subtle}`, borderRadius: 10, padding: 10, background: t.bg.base, color: t.text.primary }}>
                  <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
                    <span lang="ja" style={{ fontFamily: JA_FONT, fontSize: 26 }}>{e.k}</span>
                    <span style={{ fontSize: 13, color: t.text.secondary }}>{e.r}</span>
                  </div>
                  <div lang="ja" style={{ fontFamily: JA_FONT, fontSize: 15 }}>{e.w}</div>
                  <div style={{ fontSize: 12, color: t.text.secondary }}>{e.src}・{e.m}</div>
                </button>
              ))}
            </div>
            <div style={{ marginTop: 10 }}>
              <Note>外來音是為了拼外語，用「大字＋小字ァィゥェォ」組成一拍：ファ(fa) ≠ フア(fua)。ヴ 代表 v 音，很多詞也可以寫成バ行（ヴァイオリン＝バイオリン）。點卡片聽例字。</Note>
            </div>
          </Card>
        </div>
      ) : null}
      {mode === "srs" ? <SrsPanel /> : null}
      {mode === "kword" ? <KataRead /> : null}
      {mode === "conv" ? (
        <div style={{ display: "grid", gap: 12 }}>
          <Card>
            <Note>整個單字的平假名⇄片假名轉換：外來語用平假名寫出讀音 → 選正確的片假名；日文單字寫成片假名 → 選回平假名。選項只差一個「長得像」或「濁點不同」的字，要逐字比對！</Note>
          </Card>
          <QuizRunner key="conv" gen={convQ} />
        </div>
      ) : null}
      {mode === "boss" ? <BossRound /> : null}
      {mode === "weak5" ? <Weak5Drill /> : null}
      {mode === "dict" ? <KanaDictation /> : null}
      {mode === "mnemo" ? <MnemoPanel /> : null}
      {mode === "dash" ? (
        <KanaDash
          onPick={(r: string, s: Script) => {
            setRows([r]);
            setScript(s);
            setWeakOnly(false);
            setMode("quiz");
          }}
        />
      ) : null}
      {mode === "weak" ? (
        <WeakPanel
          onDrill={() => {
            setWeakOnly(true);
            setMode("quiz");
          }}
        />
      ) : null}
    </div>
  );
}

/* ============ 單字 ============ */
function vocabQ(v: Vocab, mode: string): Q {
  let m = mode === "mix" ? pick(["m2w", "w2r", "w2m"]) : mode;
  if (m === "w2r" && v.w === v.r) m = "w2m";
  const others = shuffle(VOCAB.filter((x: Vocab) => x.id !== v.id));
  const samePos = [...others.filter((x: Vocab) => x.p === v.p), ...others];
  const exp = `${v.w}（${v.r}）〔${v.p}〕${v.m}\n例：${v.ex}\n　　${v.tr}`;
  if (m === "m2w") {
    return { id: `vocab:${v.id}:m2w`, sec: "vocab", tag: "中文 → 選日文單字", prompt: v.m, optJa: true, ...mc(v.w, samePos.map((x: Vocab) => x.w)), exp, tts: v.r, ttsAfter: true, review: `「${v.m}」的日文` };
  }
  if (m === "w2r") {
    const sim = others.filter((x: Vocab) => x.w !== x.r && Math.abs(x.r.length - v.r.length) <= 1);
    return { id: `vocab:${v.id}:w2r`, sec: "vocab", tag: "單字 → 選讀音", prompt: v.w, big: true, ja: true, optJa: true, ...mc(v.r, [...sim, ...others].map((x: Vocab) => x.r)), exp, tts: v.r, ttsAfter: true, review: `「${v.w}」的讀音` };
  }
  return { id: `vocab:${v.id}:w2m`, sec: "vocab", tag: "單字 → 選中文意思", prompt: v.w, big: true, ja: true, ...mc(v.m, samePos.map((x: Vocab) => x.m)), exp, tts: v.r, review: `「${v.w}」的意思` };
}

function Flashcards(props: { items: Vocab[] }) {
  const t = useGrokTheme();
  const db = useDB();
  const [order, setOrder] = useState<Vocab[]>(() => shuffle(props.items));
  const [i, setI] = useState(0);
  const [flip, setFlip] = useState(false);
  const [rev, setRev] = useState(false);
  const v = order[i % Math.max(order.length, 1)];
  if (!v) return null;
  const go = (d: number) => {
    setI((x: number) => (x + d + order.length) % order.length);
    setFlip(false);
  };
  const mark = (known: boolean) => {
    const q: Q = { id: `vocab:${v.id}:card`, sec: "vocab", prompt: `單字卡：${v.w}`, options: [`${v.w}（${v.r}）${v.m}`], answer: 0, exp: `例：${v.ex}\n　　${v.tr}` };
    DB.known = { ...DB.known, [v.id]: (DB.known[v.id] ?? 0) + (known ? 1 : 0) };
    record(q, known);
    go(1);
  };
  const knownN = Object.keys(db.known).filter((k: string) => (db.known[k] ?? 0) > 0).length;
  return (
    <Card>
      <div style={{ display: "flex", justifyContent: "space-between", flexWrap: "wrap", gap: 8, marginBottom: 10 }}>
        <Note>
          第 {(i % order.length) + 1} / {order.length} 張・已記住 {knownN} 個
        </Note>
        <div style={{ display: "flex", gap: 6 }}>
          <Btn small on={rev} label="先看中文" onClick={() => { setRev(!rev); setFlip(false); }} />
          <Btn small label="重新洗牌" onClick={() => { setOrder(shuffle(props.items)); setI(0); setFlip(false); }} />
        </div>
      </div>
      <div
        role="button"
        tabIndex={0}
        onClick={() => setFlip(!flip)}
        style={{ cursor: "pointer", minHeight: 200, borderRadius: 12, background: t.bg.subtle, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: 20, textAlign: "center", gap: 8 }}
      >
        {!flip ? (
          rev ? (
            <div style={{ fontSize: 28 }}>{v.m}</div>
          ) : (
            <div lang="ja" style={{ fontFamily: JA_FONT, fontSize: 44 }}>{v.w}</div>
          )
        ) : (
          <div style={{ display: "grid", gap: 8 }}>
            <div>
              <Ruby w={v.w} r={v.r} size={40} />
            </div>
            <div style={{ fontSize: 13, color: t.text.secondary }}>{v.p}</div>
            <div style={{ fontSize: 20 }}>{v.m}</div>
            <div lang="ja" style={{ fontFamily: JA_FONT, fontSize: 16, marginTop: 6, lineHeight: 2 }}><Rich text={v.ex} /></div>
            <div style={{ fontSize: 14, color: t.text.secondary }}>{v.tr}</div>
          </div>
        )}
        <div style={{ fontSize: 12, color: t.text.secondary, marginTop: 6 }}>{flip ? "" : "點卡片翻面"}</div>
      </div>
      <div style={{ display: "flex", gap: 6, marginTop: 12, flexWrap: "wrap", justifyContent: "center" }}>
        <Btn label="← 上一張" onClick={() => go(-1)} />
        <Btn label="🔊 單字" onClick={() => speak(v.r)} />
        <Btn label="🔊 例句" onClick={() => speak(v.ex)} />
        <Btn label="✗ 還不熟" onClick={() => mark(false)} />
        <Btn kind="primary" label="✓ 記住了" onClick={() => mark(true)} />
      </div>
      <div style={{ marginTop: 8, textAlign: "center" }}>
        <Note>「還不熟」會加入錯題本；「記住了」會把它從錯題本移除。</Note>
      </div>
    </Card>
  );
}

function VocabTab() {
  const t = useGrokTheme();
  const [sub, setSub] = useState<"srs" | "card" | "quiz" | "list">("srs");
  const [lim, setLim] = useState(120);
  const [pos, setPos] = useState("all");
  const [topic, setTopic] = useState("all");
  const [mode, setMode] = useState("mix");
  const [qq, setQq] = useState("");
  const items = useMemo(() => VOCAB.filter((v: Vocab) => posMatch(v, pos) && topicMatch(v, topic)), [pos, topic]);
  const topicOpts = useMemo((): [string, string][] => {
    const o = TOPICS.map(([k, l]: [string, string]): [string, string] => [k, k === "all" ? l : `${l} ${VOCAB.filter((v: Vocab) => topicMatch(v, k)).length}`]);
    const other = VOCAB.filter((v: Vocab) => topicMatch(v, "other")).length;
    return other ? [...o, ["other", `其他 ${other}`]] : o;
  }, []);
  const gen = useMemo(() => {
    const d = deck(items);
    return () => vocabQ(d(), mode);
  }, [items, mode]);
  const shown = items.filter((v: Vocab) => !qq || v.w.includes(qq) || v.r.includes(qq) || v.m.includes(qq));
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Chips value={sub} onChange={setSub} options={[["srs", "🗂 SRS 記憶卡"], ["card", "翻卡瀏覽"], ["quiz", "選擇測驗"], ["list", `單字表（${VOCAB.length}）`]]} />
      <Chips small value={pos} onChange={setPos} options={POS} />
      <Chips small value={topic} onChange={setTopic} options={topicOpts} />
      {items.length === 0 ? <Note>這個詞性＋主題的組合沒有單字，換一個試試。</Note> : null}
      {sub === "srs" && items.length ? <VocabSRS key={`${pos}|${topic}`} items={items} /> : null}
      {sub === "card" && items.length ? <Flashcards key={`${pos}|${topic}`} items={items} /> : null}
      {sub === "quiz" ? (
        <div style={{ display: "grid", gap: 12 }}>
          <Chips small value={mode} onChange={setMode} options={[["mix", "混合"], ["m2w", "中文→單字"], ["w2r", "單字→讀音"], ["w2m", "單字→中文"]]} />
          {items.length ? <QuizRunner key={`${pos}|${topic}|${mode}`} gen={gen} /> : null}
        </div>
      ) : null}
      {sub === "list" ? (
        <Card>
          <input
            value={qq}
            onChange={(e: ChangeEvent<HTMLInputElement>) => setQq(e.target.value)}
            placeholder="搜尋：漢字、讀音或中文"
            style={{ width: "100%", boxSizing: "border-box", font: "inherit", padding: "8px 12px", borderRadius: 8, border: `1px solid ${t.border.default}`, background: t.bg.base, color: t.text.primary, marginBottom: 12 }}
          />
          <div style={{ display: "grid", gap: 8 }}>
            {shown.slice(0, lim).map((v: Vocab) => (
              <div key={v.id} style={{ borderBottom: `1px solid ${t.border.subtle}`, paddingBottom: 8 }}>
                <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap" }}>
                  <Ruby w={v.w} r={v.r} size={22} />
                  <span style={{ fontSize: 12, color: t.text.secondary }}>{v.p}</span>
                  <span>{v.m}</span>
                  <Speak text={v.r} />
                </div>
                <div style={{ fontSize: 14, marginTop: 4, display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
                  <span lang="ja" style={{ fontFamily: JA_FONT, lineHeight: 2 }}><Rich text={v.ex} /></span>
                  <Speak text={v.ex} />
                </div>
                <div style={{ fontSize: 13, color: t.text.secondary }}>{v.tr}</div>
                <KanjiLinks w={v.w} />
              </div>
            ))}
            {shown.length > lim ? <Btn label={`顯示更多（還有 ${shown.length - lim} 個）`} onClick={() => setLim(lim + 200)} /> : null}
          </div>
        </Card>
      ) : null}
    </div>
  );
}

/* ============ 文法 ============ */
function gramQ(g: Gram): Q {
  return {
    id: `grammar:${g.id}`,
    sec: "grammar",
    tag: "文法填空",
    prompt: "（　　）中放入哪個最合適？\n" + g.blank,
    ja: true,
    optJa: true,
    ...mc(g.ans, g.d),
    exp: `${g.pat}：${g.m}\n接續：${g.conn}\n${g.full}\n${g.tr}`,
    tts: g.full,
    ttsAfter: true,
    review: g.blank,
  };
}
function cmpQ(gi: number, qi: number): Q {
  const g = CMP[gi] ?? CMP[0]!;
  const q = g.qs[qi] ?? g.qs[0]!;
  const slot = !g.ask;
  const full = slot ? q.s.replace("（　　）", q.a) : q.s;
  return {
    id: `grammar:cmp${gi}_${qi}`,
    sec: "grammar",
    tag: `易混文法：${g.short}`,
    prompt: slot ? "（　　）中放入哪個最合適？\n" + q.s : `${g.ask}\n${q.s}`,
    ja: true,
    optJa: slot,
    ...mc(q.a, q.d),
    exp: `${q.e}\n——\n${g.pts.join("\n")}`,
    tts: full,
    ttsAfter: slot,
    review: q.s,
  };
}
let PENDING_CMP: string | null = null;
let PENDING_GRAM = -1;
const CMP_LINK: Record<string, string[]> = {
  "ようにする／ことにする": ["～ようにする", "～ことにする", "～ようになる", "～ことになる"],
  "ばかり": ["～ばかり（している）", "～たばかり"],
  "わけ": ["～わけではない", "～わけがない", "～わけだ", "～わけにはいかない"],
  "そうだ": ["～そうだ（傳聞）", "～そうだ（樣態）"],
  "ために／ように": ["～ために", "～ように（目的）"],
  "うちに／間": ["～うちに", "～ないうちに", "～間に"],
  "ところだ": ["～ところだ", "～たところ", "～ところに"],
  "ても／のに": ["～ても", "～のに", "たとえ～ても"],
  "尊敬語／謙譲語": ["尊敬語・特別動詞", "謙譲語・特別動詞"],
};
function cmpFor(pat: string): number[] {
  return CMP.map((c: Cmp, i: number): [Cmp, number] => [c, i]).filter((x: [Cmp, number]) => (CMP_LINK[x[0].short] ?? []).includes(pat)).map((x: [Cmp, number]) => x[1]);
}
function CmpPanel() {
  const t = useGrokTheme();
  const [g, setG] = useState(() => { const v = PENDING_CMP ?? "all"; PENDING_CMP = null; return v; });
  const gen = useMemo(() => {
    const items: [number, number][] = CMP.flatMap((c: Cmp, gi: number) => c.qs.map((_q: CmpQ, qi: number): [number, number] => [gi, qi])).filter((x: [number, number]) => g === "all" || String(x[0]) === g);
    const d = deck(items);
    return () => {
      const [gi, qi] = d();
      return cmpQ(gi, qi);
    };
  }, [g]);
  const shown = CMP.map((c: Cmp, i: number): [Cmp, number] => [c, i]).filter((x: [Cmp, number]) => g === "all" || String(x[1]) === g);
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Chips small value={g} onChange={setG} options={[["all", `全部 ${CMP.reduce((s: number, c: Cmp) => s + c.qs.length, 0)} 題`], ...CMP.map((c: Cmp, i: number): [string, string] => [String(i), c.short])]} />
      <QuizRunner key={g} gen={gen} />
      {shown.map(([c, i]: [Cmp, number]) => (
        <Card key={i} title={c.t}>
          <div style={{ display: "grid", gap: 6 }}>
            {c.pts.map((p: string, j: number) => (
              <div key={j} style={{ fontSize: 14, lineHeight: 1.7, borderLeft: `3px solid ${t.fill.accent}`, paddingLeft: 8 }}>
                {p}
              </div>
            ))}
          </div>
        </Card>
      ))}
    </div>
  );
}
function GrammarTab() {
  const t = useGrokTheme();
  const [sub, setSub] = useState<"list" | "fill" | "order" | "cmp">(() => (PENDING_GRAM >= 0 ? "fill" : "list"));
  const [qq, setQq] = useState("");
  const genFill = useMemo(() => {
    const d = deck(GRAMMAR);
    return () => {
      const pg = GRAMMAR[PENDING_GRAM];
      PENDING_GRAM = -1;
      return gramQ(pg ?? d());
    };
  }, [sub]);
  const genOrder = useMemo(() => {
    const d = deck(ORDER);
    return () => orderQ(d(), "grammar", "句子排序（★ 題）");
  }, []);
  const shown = GRAMMAR.filter((g: Gram) => !qq || g.pat.includes(qq) || g.m.includes(qq) || plain(g.ex).includes(qq));
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Chips value={sub} onChange={setSub} options={[["list", `文法一覽（${GRAMMAR.length}）`], ["fill", "填空選擇"], ["order", `句子排序 ★（${ORDER.length}）`], ["cmp", `易混文法比較（${CMP.length} 組）`]]} />
      {sub === "cmp" ? <CmpPanel /> : null}
      {sub === "fill" ? <QuizRunner gen={genFill} /> : null}
      {sub === "order" ? <QuizRunner gen={genOrder} /> : null}
      {sub === "list" ? (
        <Card>
          <input
            value={qq}
            onChange={(e: ChangeEvent<HTMLInputElement>) => setQq(e.target.value)}
            placeholder="搜尋文法，例如：ように、ばかり、聽說"
            style={{ width: "100%", boxSizing: "border-box", font: "inherit", padding: "8px 12px", borderRadius: 8, border: `1px solid ${t.border.default}`, background: t.bg.base, color: t.text.primary, marginBottom: 12 }}
          />
          <div style={{ display: "grid", gap: 10 }}>
            {shown.map((g: Gram, i: number) => (
              <div key={g.id} style={{ border: `1px solid ${t.border.subtle}`, borderRadius: 10, padding: 12 }}>
                <div style={{ display: "flex", gap: 10, alignItems: "baseline", flexWrap: "wrap" }}>
                  <span style={{ fontSize: 12, color: t.text.secondary }}>{GRAMMAR.indexOf(g) + 1 || i + 1}</span>
                  <span lang="ja" style={{ fontFamily: JA_FONT, fontSize: 19, fontWeight: 600 }}>{g.pat}</span>
                  <span>{g.m}</span>
                </div>
                <div style={{ fontSize: 13, color: t.text.secondary, margin: "4px 0" }}>接續：{g.conn}</div>
                <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
                  <span lang="ja" style={{ fontFamily: JA_FONT, fontSize: 15 }}>
                    {g.ex.split(/\{|\}/).map((p: string, j: number) => (j === 1 ? <b key={j} style={{ color: t.text.accent }}><RubyText text={p} /></b> : <RubyText key={j} text={p} />))}
                  </span>
                  <Speak text={g.full} />
                </div>
                <div style={{ fontSize: 13, color: t.text.secondary }}>{g.tr}</div>
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 8 }}>
                  <Btn small label="✏️ 練這個文法" onClick={() => { PENDING_GRAM = GRAMMAR.indexOf(g); setSub("fill"); window.scrollTo(0, 0); }} />
                  {cmpFor(g.pat).map((ci: number) => (
                    <Btn key={ci} small label={`⚖️ 比較：${CMP[ci]?.short ?? ""}`} onClick={() => { PENDING_CMP = String(ci); setSub("cmp"); window.scrollTo(0, 0); }} />
                  ))}
                </div>
              </div>
            ))}
          </div>
        </Card>
      ) : null}
    </div>
  );
}

/* ============ 模擬考 ============ */
type ExItem = { cat: string; id: string; mk: () => Q };
type ExSec = { name: string; min: number; items: ExItem[] };
const LT_NAME: Record<string, string> = { m: "聽句子選意思", f: "聽寫填空", r: "即時応答", k: "課題理解", p: "ポイント理解" };
function exItem(cat: string, mk: () => Q): ExItem {
  return { cat, id: mk().id, mk };
}
function buildExam(): ExSec[] {
  const by = (s: string, n: number): ExItem[] => shuffle(MOCK.filter((m: MQ) => m.s === s)).slice(0, n).map((m: MQ) => exItem(s, m.mk));
  const groups = new Map<string, MQ[]>();
  MOCK.filter((m: MQ) => m.s === "読解").forEach((m: MQ) => {
    const k = m.mk().passage ?? m.id;
    groups.set(k, [...(groups.get(k) ?? []), m]);
  });
  const rd: ExItem[] = [];
  shuffle(Array.from(groups.values())).forEach((g: MQ[]) => {
    if (rd.length < 16) g.forEach((m: MQ) => rd.push(exItem("読解", m.mk)));
  });
  const L = (tt: string, n: number): ExItem[] => shuffle(LISTEN.filter((l: LI) => tt.includes(l.t))).slice(0, n).map((l: LI) => exItem(LT_NAME[l.t] ?? l.t, () => listenQ(l)));
  return [
    { name: "言語知識（文字・語彙）", min: 30, items: [...by("漢字読み", 8), ...by("表記", 6), ...by("文脈規定", 11), ...by("言い換え類義", 5), ...by("用法", 5)] },
    { name: "言語知識（文法）・読解", min: 70, items: [...by("文法形式", 13), ...by("文の組み立て", 5), ...rd] },
    { name: "聴解", min: 40, items: [...L("k", 6), ...L("p", 6), ...L("mf", 7), ...L("r", 9)] },
  ];
}
function mmss(ms: number): string {
  const s = Math.max(0, Math.ceil(ms / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}
function FullExam() {
  const t = useGrokTheme();
  const [exam, setExam] = useState<ExSec[] | null>(null);
  const [si, setSi] = useState(0);
  const [phase, setPhase] = useState<"intro" | "run" | "brk" | "done">("intro");
  const [res, setRes] = useState<Record<string, boolean>>({});
  const [end, setEnd] = useState(0);
  const [now, setNow] = useState(() => Date.now());
  const [scale, setScale] = useState("1");
  const idx = useRef(0);
  const savedRnd = useRef(false);
  const begin = (i: number, ex: ExSec[]) => {
    idx.current = 0;
    setSi(i);
    setEnd(Date.now() + (ex[i]?.min ?? 30) * 60e3 * Number(scale));
    setNow(Date.now());
    setPhase("run");
  };
  const finish = () => setPhase(si >= 2 ? "done" : "brk");
  useEffect(() => {
    if (phase !== "run") return undefined;
    const id = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(id);
  }, [phase]);
  useEffect(() => {
    if (phase === "run" && end > 0 && now >= end) setPhase(si >= 2 ? "done" : "brk");
  }, [now, phase, end, si]);
  const gen = useMemo(() => {
    const items = exam?.[si]?.items ?? [];
    return (): Q => {
      const it = items[Math.min(idx.current, Math.max(0, items.length - 1))];
      return it ? it.mk() : (MOCK[0] as MQ).mk();
    };
  }, [exam, si]);
  const sec = exam?.[si];
  const answered = (s: number) => Object.keys(res).filter((k: string) => k.startsWith(`${s}|`)).length;
  const correct = (s: number) => Object.keys(res).filter((k: string) => k.startsWith(`${s}|`) && res[k]).length;
  if (phase === "intro" || !exam || !sec) {
    return (
      <Card title="⏱ JLPT N3 計時模考（三節、分節計時）">
        <div style={{ display: "grid", gap: 10, fontSize: 14, lineHeight: 1.7 }}>
          <div>① 言語知識（文字・語彙）約 35 題・30 分<br />② 言語知識（文法）・読解 約 34 題・70 分<br />③ 聴解 28 題・40 分（課題理解・ポイント理解・聞句子・即時応答）</div>
          <Chips small value={scale} onChange={setScale} options={[["1", "正式時間（30／70／40 分）"], ["0.5", "衝刺版（時間減半）"]]} />
          <Note>題型題數仿照 N3 正式考試，題目從題庫隨機抽取（全部原創）。時間到會自動交卷，沒作答的題算錯。結束後依「言語知識／読解／聴解」三個得分區分各以 60 分換算，並用正式合格標準（總分 95/180、各區分 19 分以上）粗估。</Note>
          <div>
            <Btn
              kind="primary"
              label="開始模考"
              onClick={() => {
                const ex = buildExam();
                setExam(ex);
                setRes({});
                savedRnd.current = false;
                begin(0, ex);
              }}
            />
          </div>
        </div>
      </Card>
    );
  }
  if (phase === "brk") {
    const nx = exam[si + 1];
    return (
      <Card title={`第 ${si + 1} 節結束：${sec.name}`}>
        <div style={{ display: "grid", gap: 10 }}>
          <div style={{ fontSize: 15 }}>
            作答 {answered(si)}/{sec.items.length} 題、答對 {correct(si)} 題
          </div>
          <Note>休息一下，準備好再開始下一節（正式考試「文字・語彙」與「文法・読解」之間不休息，聴解前有休息）。</Note>
          {nx ? (
            <div>
              <Btn kind="primary" label={`開始第 ${si + 2} 節：${nx.name}`} onClick={() => begin(si + 1, exam)} />
            </div>
          ) : null}
        </div>
      </Card>
    );
  }
  if (phase === "done") {
    const grp = (f: (s: number, it: ExItem) => boolean) => {
      let n = 0;
      let c = 0;
      exam.forEach((x: ExSec, s: number) =>
        x.items.forEach((it: ExItem) => {
          if (f(s, it)) {
            n++;
            if (res[`${s}|${it.id}`]) c++;
          }
        })
      );
      return { n, c, p: n ? Math.round((c / n) * 60) : 0 };
    };
    const parts: [string, { n: number; c: number; p: number }][] = [
      ["言語知識（文字・語彙・文法）", grp((s: number, it: ExItem) => s === 0 || (s === 1 && it.cat !== "読解"))],
      ["読解", grp((s: number, it: ExItem) => s === 1 && it.cat === "読解")],
      ["聴解", grp((s: number) => s === 2)],
    ];
    const total = parts.reduce((a: number, x: [string, { n: number; c: number; p: number }]) => a + x[1].p, 0);
    if (!savedRnd.current) { savedRnd.current = true; window.setTimeout(() => { DB.exams = [...(DB.exams ?? []), { n: 0, t: Date.now(), p: parts.map((x) => x[1].p), tot: total }].slice(-50); commit(); }, 0); }
    const pass = total >= 95 && parts.every((x: [string, { n: number; c: number; p: number }]) => x[1].p >= 19);
    const cats: { cat: string; n: number; c: number }[] = [];
    exam.forEach((x: ExSec, s: number) =>
      x.items.forEach((it: ExItem) => {
        let e = cats.find((y: { cat: string; n: number; c: number }) => y.cat === it.cat);
        if (!e) {
          e = { cat: it.cat, n: 0, c: 0 };
          cats.push(e);
        }
        e.n++;
        if (res[`${s}|${it.id}`]) e.c++;
      })
    );
    return (
      <Card title="📊 模考成績單">
        <div style={{ display: "grid", gap: 10 }}>
          {parts.map(([nm, x]: [string, { n: number; c: number; p: number }]) => (
            <div key={nm} style={{ display: "grid", gridTemplateColumns: "minmax(120px, 200px) 1fr 76px", gap: 8, alignItems: "center", fontSize: 14 }}>
              <span>{nm}</span>
              <Bar v={x.p / 60} color={x.p >= 19 ? t.text.success : t.text.danger} label={`${nm} ${x.p} 分`} />
              <span style={{ textAlign: "right" }}>
                <b>{x.p}</b>/60（{x.c}/{x.n}）
              </span>
            </div>
          ))}
          <div style={{ fontSize: 20, fontWeight: 600, color: pass ? t.text.success : t.text.danger }}>
            總分 {total}/180　{pass ? "✅ 推估合格" : "❌ 推估未達合格標準"}
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))", gap: 6 }}>
            {cats.map((x: { cat: string; n: number; c: number }) => (
              <div key={x.cat} style={{ border: `1px solid ${t.border.subtle}`, borderRadius: 8, padding: "6px 8px", fontSize: 13 }}>
                <div style={{ color: t.text.secondary }}>{x.cat}</div>
                <div>
                  {x.c}/{x.n}（{x.n ? Math.round((x.c / x.n) * 100) : 0}%）
                </div>
              </div>
            ))}
          </div>
          <Note>正式 JLPT 採用「尺度得分」，這裡用「答對率 × 60」粗估，僅供參考。合格標準：總分 95 分以上，且三個得分區分都要 19 分以上。答錯的題已加入「錯題・成績」。</Note>
          <div>
            <Btn kind="primary" label="再考一次（重新抽題）" onClick={() => setPhase("intro")} />
          </div>
        </div>
      </Card>
    );
  }
  const rem = end - now;
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <div style={{ position: "sticky", top: 0, zIndex: 2, background: t.bg.base, paddingBottom: 4 }}>
        <Card style={{ padding: 10 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
            <span style={{ fontSize: 14, fontWeight: 600 }}>
              第 {si + 1}/3 節：{sec.name}
            </span>
            <span role="timer" aria-label={`剩餘時間 ${mmss(rem)}`} style={{ fontSize: 18, fontWeight: 600, fontVariantNumeric: "tabular-nums", color: rem < 5 * 60e3 ? t.text.danger : t.text.primary }}>
              ⏱ {mmss(rem)}
            </span>
            <Btn small label="交卷（結束本節）" onClick={finish} />
          </div>
          <div style={{ marginTop: 6 }}>
            <Bar v={rem / ((sec.min || 1) * 60e3 * Number(scale))} color={rem < 5 * 60e3 ? t.text.danger : t.text.accent} label="剩餘時間" />
          </div>
        </Card>
      </div>
      <QuizRunner
        key={`ex${si}`}
        gen={gen}
        total={sec.items.length}
        onResult={(q: Q, ok: boolean) => {
          idx.current++;
          setRes((r: Record<string, boolean>) => ({ ...r, [`${si}|${q.id}`]: ok }));
        }}
        onDone={finish}
      />
    </div>
  );
}
function MockTab() {
  const [sec, setSec] = useState("all");
  const [mode, setMode] = useState("sets");
  const full = mode === "full";
  const items = useMemo(() => MOCK.filter((m: MQ) => sec === "all" || m.s === sec), [sec]);
  const gen = useMemo(() => {
    if (full) {
      let i = 0;
      return () => {
        const m = MOCK[i % MOCK.length]!;
        i++;
        return m.mk();
      };
    }
    const d = deck(items);
    return () => d().mk();
  }, [items, full]);
  const opts: [string, string][] = [["all", "全部"], ...MOCK_SECS.map((s: string): [string, string] => [s, `${s}（${MOCK.filter((m: MQ) => m.s === s).length}）`])];
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Card>
        <div style={{ display: "grid", gap: 10 }}>
          <Chips value={mode} onChange={setMode} options={[["sets", `📚 第1–${EXAMS.length}回 模考`], ["prac", "分項練習（隨機）"], ["full", `完整模考（${MOCK.length} 題，依題型順序）`], ["exam", "⏱ 計時模考（N3 正式時間）"]]} />
          {mode === "prac" ? <Chips small value={sec} onChange={setSec} options={opts} /> : null}
          <Note>全部為原創「模擬題」，仿照 JLPT N3 題型（文字・語彙、文法、讀解），並非官方考古題。</Note>
        </div>
      </Card>
      {mode === "sets" ? <ExamSets /> : mode === "exam" ? <FullExam /> : <QuizRunner key={`${sec}|${full}`} gen={gen} total={full ? MOCK.length : undefined} />}
    </div>
  );
}

/* ============ 聽力 ============ */
function listenQ(l: LI): Q {
  if (l.t === "k" || l.t === "p") {
    const turns = furiK(l.id, l.s).split("＃");
    return {
      id: `listen:${l.id}`,
      sec: "listen",
      tag: l.t === "k" ? "課題理解：聽對話，判斷接下來要做什麼" : "ポイント理解：聽對話，抓住理由或重點",
      prompt: "🎧 先看問題，再聽對話（男聲低、女聲高）：\n" + furiK("lq" + l.id.slice(2), l.q ?? ""),
      ja: true,
      optJa: true,
      ...mc(l.o[0] ?? "", l.o.slice(1)),
      tts: turns.join("＃"),
      autoPlay: true,
      reveal: turns.join("\n"),
      exp: l.e,
      review: (l.q ?? "") + "\n" + l.s.split("＃").join("\n"),
    };
  }
  const isM = l.t === "m";
  const isR = l.t === "r";
  const ans = l.o[0] ?? "";
  return {
    id: `listen:${l.id}`,
    sec: "listen",
    tag: isR ? "即時応答：選出最適當的回應" : isM ? "聽句子 → 選意思" : "聽句子 → 選出空格的詞",
    prompt: isR ? "🎧 聽對方說的話，選出最適當的回應。\n（題目文字答完才顯示）" : isM ? "🎧 聽完句子，選出正確的中文意思。" : "🎧 聽句子，選出（　　）中聽到的詞：\n" + l.s.replace(ans, "（　　）"),
    ja: !isM,
    optJa: !isM,
    ...mc(ans, l.o.slice(1)),
    tts: furiK(l.id, l.s),
    autoPlay: true,
    reveal: furiK(l.id, l.s),
    exp: l.e,
    review: l.s,
  };
}
function ListenTab() {
  const [slow, setSlow] = useState(false);
  const [hasJa, setHasJa] = useState<boolean | null>(null);
  useEffect(() => {
    RATE = slow ? 0.65 : 0.9;
    return () => {
      RATE = 0.9;
    };
  }, [slow]);
  useEffect(() => {
    try {
      const ss = window.speechSynthesis;
      if (!ss) {
        setHasJa(false);
        return;
      }
      const check = () => setHasJa(ss.getVoices().some((v: SpeechSynthesisVoice) => v.lang.toLowerCase().startsWith("ja")));
      check();
      ss.onvoiceschanged = check;
    } catch {
      setHasJa(false);
    }
  }, []);
  const [lt, setLt] = useState("all");
  const gen = useMemo(() => {
    const d = deck(LISTEN.filter((l: LI) => lt === "all" || l.t === lt));
    return () => listenQ(d());
  }, [lt]);
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Card>
        <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
          <Btn on={slow} label={slow ? "✓ 慢速播放" : "慢速播放"} onClick={() => setSlow(!slow)} />
          <Note>
            共 {LISTEN.length} 題，使用瀏覽器內建日語語音（TTS）。
            {hasJa === false ? "偵測不到日語語音：請在手機／電腦的語音設定中加入「日本語」語音，或改用 Chrome／Safari。" : ""}
          </Note>
        </div>
        <div style={{ marginTop: 10 }}>
          <Chips
            small
            value={lt}
            onChange={setLt}
            options={[
              ["all", `全部 ${LISTEN.length}`],
              ["m", `聽意思 ${LISTEN.filter((l: LI) => l.t === "m").length}`],
              ["f", `聽寫填空 ${LISTEN.filter((l: LI) => l.t === "f").length}`],
              ["r", `即時応答 ${LISTEN.filter((l: LI) => l.t === "r").length}`],
              ["k", `課題理解 ${LISTEN.filter((l: LI) => l.t === "k").length}`],
              ["p", `ポイント理解 ${LISTEN.filter((l: LI) => l.t === "p").length}`],
            ]}
          />
        </div>
      </Card>
      <QuizRunner key={lt} gen={gen} />
    </div>
  );
}

/* ============ 歌曲 ============ */
function LyricsTool() {
  const t = useGrokTheme();
  const db = useDB();
  const [text, setText] = useState(db.lyrics);
  const [built, setBuilt] = useState<{ lines: string[]; pool: string[]; v: number } | null>(null);
  const [err, setErr] = useState("");
  const build = () => {
    DB.lyrics = text;
    commit();
    const lines = text
      .split(/\n/)
      .map((s: string) => s.trim())
      .filter((s: string) => lyricTokens(s).length > 0);
    const pool = uniq(lines.flatMap(lyricTokens));
    if (pool.length < 4) {
      setErr("可挖空的詞太少（需要至少 4 個不同的漢字詞或片假名詞），請貼上較長的歌詞。");
      setBuilt(null);
      return;
    }
    setErr("");
    setBuilt({ lines, pool, v: Date.now() });
  };
  const gen = useMemo(() => {
    if (!built) return null;
    const d = deck(built.lines);
    return (): Q => {
      const line = d();
      const tok = pick(lyricTokens(line));
      const sim = shuffle(built.pool.filter((x: string) => x !== tok && Math.abs(x.length - tok.length) <= 1));
      const rest = shuffle(built.pool.filter((x: string) => x !== tok));
      return {
        id: `song:${line.slice(0, 40)}:${tok}`,
        sec: "song",
        tag: "歌詞填空",
        prompt: "（　　）中是哪個詞？\n" + line.split(tok).join("（　　）"),
        ja: true,
        optJa: true,
        ...mc(tok, [...sim, ...rest]),
        exp: line,
        tts: line,
        ttsAfter: true,
        review: line.split(tok).join("（　　）"),
      };
    };
  }, [built]);
  return (
    <Card title="自製歌詞填空">
      <Note>從官方歌詞網站複製歌詞，貼到下面。系統會自動把每行的漢字詞或片假名詞挖空出選擇題。歌詞只存在你這個瀏覽器，不會上傳。</Note>
      <textarea
        value={text}
        onChange={(e: ChangeEvent<HTMLTextAreaElement>) => setText(e.target.value)}
        placeholder="在這裡貼上歌詞（一行一句）…"
        rows={7}
        lang="ja"
        style={{ width: "100%", boxSizing: "border-box", marginTop: 10, font: "inherit", fontFamily: JA_FONT, padding: 10, borderRadius: 8, border: `1px solid ${t.border.default}`, background: t.bg.base, color: t.text.primary, resize: "vertical" }}
      />
      <div style={{ display: "flex", gap: 8, marginTop: 8, flexWrap: "wrap" }}>
        <Btn kind="primary" label="產生填空題" onClick={build} />
        {text ? (
          <Btn
            label="清除歌詞"
            onClick={() => {
              setText("");
              setBuilt(null);
              DB.lyrics = "";
              commit();
            }}
          />
        ) : null}
      </div>
      {err ? <div style={{ color: t.text.danger, fontSize: 13, marginTop: 8 }}>{err}</div> : null}
      {built && gen ? (
        <div style={{ marginTop: 12 }}>
          <Note>
            {built.lines.length} 行、{built.pool.length} 個可挖空詞
          </Note>
          <div style={{ marginTop: 8 }}>
            <QuizRunner key={built.v} gen={gen} />
          </div>
        </div>
      ) : null}
    </Card>
  );
}
const SONG_MORE: { v: [string, string, string][]; g: string[] }[] = [
  {
    v: [["切ない", "せつない", "揪心、難受"], ["二度と", "にどと", "再也（不）"], ["暗闇", "くらやみ", "黑暗"], ["胸", "むね", "胸口"], ["戻る", "もどる", "返回"], ["苦しい", "くるしい", "痛苦"], ["笑顔", "えがお", "笑容"], ["傷", "きず", "傷"]],
    g: ["二度と～ない（再也不…）", "～たまま（保持…的狀態）", "～ように（像…一樣／但願…）", "～てしまう（遺憾、無法挽回）"],
  },
  {
    v: [["叫ぶ", "さけぶ", "大喊"], ["未来", "みらい", "未來"], ["嘘", "うそ", "謊言"], ["正義", "せいぎ", "正義"], ["我慢", "がまん", "忍耐"], ["夢中", "むちゅう", "著迷、入神"], ["大人", "おとな", "大人"], ["若者", "わかもの", "年輕人"]],
    g: ["～なんて（表輕視或意外：…之類的）", "～たって（＝～ても，口語）", "～ないでよ（口語：別…啦）", "～じゃない（口語：不是…嗎）"],
  },
  {
    v: [["寂しい", "さびしい", "寂寞"], ["恋人", "こいびと", "戀人"], ["振り返る", "ふりかえる", "回頭、回顧"], ["都会", "とかい", "都市"], ["夜明け", "よあけ", "黎明"], ["鳴る", "なる", "響"], ["心", "こころ", "心"], ["約束", "やくそく", "約定"]],
    g: ["～まま（維持原狀）", "～ていく（…下去：時間推移）", "～ば（假定條件）", "～なら（如果是…的話）"],
  },
  {
    v: [["魂", "たましい", "靈魂"], ["誓う", "ちかう", "發誓"], ["仲間", "なかま", "夥伴"], ["勇気", "ゆうき", "勇氣"], ["負ける", "まける", "輸"], ["命", "いのち", "生命"], ["闇", "やみ", "黑暗"], ["刃", "やいば", "刀刃"]],
    g: ["～ずに（不…而…）", "～しかない（只能…）", "～ても（即使…也）", "～とおりに（按照…）"],
  },
];
type SV = { w: string; r: string; m: string; song: string };
const SONG_VOCAB: SV[] = SONGS.flatMap((s: Song, i: number) => [...s.v, ...(SONG_MORE[i]?.v ?? [])].map((v: [string, string, string]) => ({ w: v[0], r: v[1], m: v[2], song: s.t })));
function songVocabQ(x: SV): Q {
  const others = shuffle(SONG_VOCAB.filter((y: SV) => y.w !== x.w));
  const exp = `${x.w}（${x.r}）：${x.m}`;
  if (Math.random() < 0.5) {
    return { id: `song:v:${x.w}:m`, sec: "song", tag: `主題詞彙・${x.song}`, prompt: x.w, big: true, ja: true, ...mc(x.m, others.map((y: SV) => y.m)), tts: x.r, exp };
  }
  return { id: `song:v:${x.w}:w`, sec: "song", tag: `主題詞彙・${x.song}`, prompt: x.m, optJa: true, ...mc(x.w, others.map((y: SV) => y.w)), tts: x.r, ttsAfter: true, exp };
}
function SongVocabQuiz() {
  const [open, setOpen] = useState(false);
  const gen = useMemo(() => {
    const d = deck(SONG_VOCAB);
    return () => songVocabQ(d());
  }, []);
  return (
    <Card title={`歌曲主題詞彙小測驗（${SONG_VOCAB.length} 個）`}>
      {open ? <QuizRunner gen={gen} /> : <Btn kind="primary" label="開始練習" onClick={() => setOpen(true)} />}
    </Card>
  );
}
