            {mode === "view" ? <LyricsView s={s} lines={lines} toks={toks} /> : null}
            {mode === "fill" ? (tk ? <LyricsFill s={s} lines={lines} toks={toks} /> : <Note>需要斷詞字典才能出填空題。</Note>) : null}
